flow.set('catalogue', []);
node.warn('DSP catalogue: /data/dsp-config/datasets.json missing — serving empty catalogue. Mount the ConfigMap.');
return null;

// Derives the catalogue from the FACIS Data Sink's lakehouse: lists live
// gold-layer tables in Trino and merges them with datasets.json (the rich
// metadata overlay + offline fallback). Runs at startup and every 10 min.
// Availability over strictness — see this tab's info panel for the rules.
const catalog = env.get('DSP_TRINO_CATALOG') || 'fap-iotai-stackable';
const trinoUrl = env.get('DSP_TRINO_URL') || 'https://trino-coordinator.stackable.svc.cluster.local:8443';
const user = env.get('DSP_TRINO_USER') || 'admin';
const pass = env.get('DSP_TRINO_PASSWORD') || '';
const schema = 'information_schema';
const auth = 'Basic ' + Buffer.from(user + ':' + pass).toString('base64');
const sql = 'SELECT table_schema, table_name FROM "' + catalog + '".information_schema.tables WHERE table_schema = \'gold\'';

// Read the overlay first (same fs.readFileSync + DSP_DATASETS_PATH pattern as
// dsp-data-lookup-fn) so it is available both as the merge source and as the
// Trino-down fallback.
let overlay = [];
try {
    const parsed = JSON.parse(fs.readFileSync(env.get('DSP_DATASETS_PATH') || '/data/dsp-config/datasets.json', 'utf8'));
    if (Array.isArray(parsed)) overlay = parsed;
} catch (err) {
    node.warn('catalogue: could not read overlay datasets.json: ' + (err && err.message ? err.message : err));
}

function done(source) {
    // Unwired completion signal (this node has no downstream in production);
    // lets the flow-test harness observe termination without polling.
    node.send({ payload: { catalogueSource: source, size: (flow.get('catalogue') || []).length } });
}

(async () => {
    // trinoRequest: copied verbatim from dsp-data-trino-fn (facis-dsp-data.json)
    // — same nextUri-chain statement API, auth headers, and rejectUnauthorized.
    function trinoRequest(urlStr, body) {
        return new Promise((resolve, reject) => {
            const u = new urlmod.URL(urlStr);
            const mod = u.protocol === 'http:' ? http : https;
            const opts = {
                method: body ? 'POST' : 'GET',
                hostname: u.hostname,
                port: u.port || (u.protocol === 'http:' ? 80 : 443),
                path: u.pathname + u.search,
                headers: {
                    Authorization: auth,
                    'X-Trino-User': user,
                    'X-Trino-Catalog': catalog,
                    'X-Trino-Schema': schema,
                    'Content-Type': 'text/plain'
                },
                rejectUnauthorized: false
            };
            const req = mod.request(opts, (res) => {
                let data = '';
                res.on('data', (c) => { data += c; });
                res.on('end', () => {
                    try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
                });
            });
            req.on('error', reject);
            if (body) req.write(body);
            req.end();
        });
    }

    try {
        let result = await trinoRequest(trinoUrl + '/v1/statement', sql);
        let rows = [];
        let iterations = 0;
        while (result && iterations < 25) {
            iterations++;
            if (result.error) throw new Error('Trino error: ' + JSON.stringify(result.error));
            if (result.data) rows = rows.concat(result.data);
            if (!result.nextUri) break;
            result = await trinoRequest(result.nextUri, null);
        }

        // rows are [table_schema, table_name]; the query already filters gold.
        const liveTables = new Set();
        rows.forEach((r) => { if (r && r[0] && r[1]) liveTables.add(r[0] + '.' + r[1]); });

        const merged = [];
        const claimed = new Set();
        overlay.forEach((entry) => {
            const md = (entry && entry.metadata) || {};
            const key = md.schema + '.' + md.table;
            if (liveTables.has(key)) {
                merged.push(entry);
                claimed.add(key);
            } else {
                node.warn('catalogue: dropping ' + (entry && entry.id) + ' — table ' + md.schema + '.' + md.table + ' not present in lakehouse');
            }
        });

        let autoderived = 0;
        rows.forEach((r) => {
            if (!r || !r[0] || !r[1]) return;
            const key = r[0] + '.' + r[1];
            if (claimed.has(key)) return;
            const tableName = r[1];
            merged.push({
                id: 'dataset:facis:' + tableName.replace(/_/g, '-'),
                metadata: { title: tableName, description: 'Gold-layer dataset ' + tableName + ' (derived from lakehouse metadata)', assetType: 'iot.timeseries', format: 'iceberg/parquet', schema: 'gold', table: tableName, timeColumn: null },
                offers: [ { id: 'offer:facis:' + tableName.replace(/_/g, '-') + ':read', policySummary: { purpose: 'analytics', rate_limit: '10 req/min', ttl: 'PT1H' } } ]
            });
            autoderived++;
        });

        flow.set('catalogue', merged);
        flow.set('catalogueSource', 'lakehouse');
        node.log('DSP catalogue: derived ' + merged.length + ' dataset(s) from lakehouse (' + autoderived + ' auto-derived)');
        done('lakehouse');
    } catch (err) {
        const reason = err && err.message ? err.message : String(err);
        const existing = flow.get('catalogue');
        if (Array.isArray(existing) && existing.length > 0) {
            node.warn('catalogue: Trino derivation failed, keeping existing catalogue (' + existing.length + ' entries) — ' + reason);
            done(flow.get('catalogueSource') || null);
        } else {
            flow.set('catalogue', overlay);
            flow.set('catalogueSource', 'overlay-fallback');
            node.warn('catalogue: Trino derivation failed and catalogue empty, falling back to overlay file (' + overlay.length + ' entries) — ' + reason);
            done('overlay-fallback');
        }
    }
})();
return null;

const mode = (env.get('DSP_IAM_CATALOGUE') || 'open').toLowerCase();
if (mode === 'verified') {
    return [null, msg];
}
return [msg, null];

// Mirrors catalogue_store.query_catalogue() filter + cursor logic.
const datasets = flow.get('catalogue') || [];
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const filter = body.filter || {};
const page = body.page || {};

const limit = (typeof page.limit === 'number' && page.limit > 0) ? page.limit : 50;
const cursorRaw = page.cursor;

let filtered = datasets;
if (filter.assetType) {
    filtered = filtered.filter(d => d && d.metadata && d.metadata.assetType === filter.assetType);
}
if (Array.isArray(filter.datasetIds) && filter.datasetIds.length > 0) {
    const ids = new Set(filter.datasetIds);
    filtered = filtered.filter(d => d && ids.has(d.id));
}

// Python: int(cursor) on ValueError -> 0; missing/null -> 0.
let start = 0;
if (cursorRaw !== null && cursorRaw !== undefined && cursorRaw !== '') {
    const parsed = parseInt(cursorRaw, 10);
    start = Number.isFinite(parsed) && parsed >= 0 ? parsed : 0;
}

const slice = filtered.slice(start, start + limit);
const nextCursor = (start + limit) < filtered.length ? String(start + limit) : null;

msg.payload = { datasets: slice, nextCursor: nextCursor };
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
return [msg, { payload: { family: 'facis_dsp_catalogue_requests_total' } }];
